#!/usr/bin/env python3
"""Figure 7 (the paper's fig2_recovery), regenerated by LIEP-REGEN (owner's OK 2026-11-05): analog weight distortion
and what recovers from it, every arm on the same fault mask (stage 4b), and each arm with its own ceiling: the undamaged
network put through the same 3-epoch fine-tune by that arm (stage 4c). Data from figures/export.py.

The paper's version (below, its original docstring) had one ceiling for all arms, the pretrained network before any
fine-tune. Fine-tuning alone moves every arm off that value, so it was not the ceiling of any arm.

Figure 2 -- analog weight distortion and what recovers from it.

One column per fault, labelled (a)-(d) so each can be cited in the text:
  (a) additive Gaussian   (b) multiplicative log-normal
  (c) stuck at zero       (d) stuck at saturation

Each column pairs the distortion applied to a single weight with the recovery it
permits. The lock-in-vs-static-EP comparison that used to sit below now lives in
figures/src/figS1_lockin_static.py -- it answers a methods question about
estimator substitution and was pulling the narrative away from the recovery result.
"""
import os
import sys
from pathlib import Path

import numpy as np
import plotly.graph_objects as go
from plotly.subplots import make_subplots

sys.path.insert(0, str(Path(__file__).resolve().parent))
import liepfig as L

# NOTE: add_hline/add_vline/add_hrect/add_vrect default to
# exclude_empty_subplots=True when given row/col, so a shape aimed at a subplot
# that has no traces YET is silently discarded. Always pass
# exclude_empty_subplots=False. Their coordinates are DATA units even on a log
# axis, whereas add_annotation wants log10 -- see yshape().

M = L.macros("fig7")
CLEAN = float(M["FigClean"])

# Cells with too few draws to median honestly are held back; the exporter
# records n per cell and FigNdraw quotes only what is shown.
MINREPS = 3
# Revision 2026-11-13 (owner): every curve, the damaged floor included, is divided by ONE reference, the backprop
# control: the undamaged network put through the same fine-tune by backprop (stage 4c). 1 is the conventional method
# without damage; an arm can sit slightly above it. The floor is clipped at the axis bottom, its value
# printed where it leaves the panel. Linear axis, zoomed on the fine-tuned arms.
CEILS = {"Lockin": float(M["FigCeilLockin"]), "Centred": float(M["FigCeilCentred"]), "Bp": float(M["FigCeilBp"]),
         "Ro": float(M["FigCeilRo"])}
REF_ARM = "Bp"; REF = CEILS[REF_ARM]
CEIL = {k: REF for k in ("lockin", "centred", "bp", "ro", "imp")}
DATS = {k: L.dat(f"fig7_rec_{k}.dat") for k in ("gaussian", "lognormal", "stuck_zero", "stuck_sat")}
ARMHI = max(float((d[f"{c}hi"] / CEIL[c]).max()) for d in DATS.values() for c in ("lockin", "centred", "bp", "ro"))
YHI = np.ceil((ARMHI + 0.004) * 200) / 200
# Revision 2026-11-17 (owner): each recovery panel's y axis spans lock-in EP's dynamic range in that panel (its band,
# min over draws, at every severity shown), not the worst arm across the figure. Other curves that leave it are cut
# at the bottom edge; the damaged floor is still clipped there with its value printed.
YLOS = {}
for k, d in DATS.items():
    lo = float((d[d.n >= MINREPS]["lockinlo"] / CEIL["lockin"]).min())
    YLOS[k] = np.floor((lo - 0.03 * (YHI - lo)) * 100) / 100
yv = lambda a: a


def yshape(a):
    return a


# Each map's severity is a different quantity, so each panel names its own.
# Only the additive-Gaussian sigma is dimensional; it is plotted relative to the
# RMS weight so the axis is comparable in spirit with the dimensionless three.
FAULTS = [
    ("gaussian",   "a", "additive<br>Gaussian",        "w + &#963;<i>N</i>",
     "&#963; / RMS(w)"),
    ("lognormal",  "b", "multiplicative<br>log-normal", "w &#183; e<sup>&#963;<i>N</i></sup>",
     "&#963;  (log space)"),
    ("stuck_zero", "c", "stuck at<br>zero",             "fraction f &#8594; 0",
     "fraction f"),
    ("stuck_sat",  "d", "stuck at<br>saturation",       "fraction f &#8594; &#177;w<sub>max</sub>",
     "fraction f"),
]
# (data column, colour, label, line dash, ceiling macro or None)
SERIES = [("lockin", L.HEBB, "lock-in EP", "solid", "Lockin"),
          ("centred", L.HOLO, "centred EP", "solid", "Centred"),
          ("bp", L.ANTIHOLO, "backprop", "solid", "Bp"),
          ("ro", L.PROBE, "readout only", "solid", "Ro"),
          ("imp", L.BAD, "damaged, before fine-tuning", "solid", None)]

ML, MR, MT, MB = 40.0, 4.0, 30.0, 28.0      # the legend sits in the gap between the rows
(D_DIST, D_REC), PLOT_H = L.vstack(heights=[38.0, 118.0], gaps=[38.0])
TOTAL = MT + PLOT_H + MB
PT = 1.0 / PLOT_H
COLS = L.hsplit(4, gap=0.055)                # every recovery panel carries its own y tick labels

fig = make_subplots(rows=2, cols=4)


def ax(n: str, i: int) -> str:
    """Plotly names the first axis 'x'/'y', not 'x1'/'y1'."""
    return n if i == 1 else f"{n}{i}"


# ================= row 1: how each fault distorts one weight =============
W0, WMAX = 0.5, 1.0
xs = np.linspace(-1.25, 1.75, 600)


def stem(x, h, colour, col, width=1.3):
    fig.add_trace(go.Scatter(x=[x, x], y=[0, h], mode="lines",
                             line=dict(color=colour, width=L.pt(width)),
                             hoverinfo="skip"), row=1, col=col)


for i, (key, letter, name, expr, xlab) in enumerate(FAULTS):
    c = i + 1
    fig.add_trace(go.Scatter(x=[-1.25, 1.75], y=[0, 0], mode="lines",
                             line=dict(color=L.GRAY, width=L.pt(0.4)),
                             hoverinfo="skip"), row=1, col=c)
    stem(W0, 1.0, L.GRAY, c, width=0.9)                 # the intended value
    if key == "gaussian":
        y = np.exp(-0.5 * ((xs - W0) / 0.30) ** 2)
    elif key == "lognormal":
        y = np.zeros_like(xs)
        pos = xs > 1e-3
        u = np.log(xs[pos] / W0) / 0.55
        y[pos] = np.exp(-0.5 * u ** 2) / (xs[pos] / W0)
        y /= y.max()
    else:
        y = None
    if y is not None:
        fig.add_trace(go.Scatter(x=xs, y=y, mode="lines", fill="tozeroy",
                                 fillcolor=L.rgba(L.BAD, 0.28),
                                 line=dict(color=L.BAD, width=L.pt(1.0)),
                                 hoverinfo="skip"), row=1, col=c)
    elif key == "stuck_zero":
        stem(W0, 0.62, L.BAD, c); stem(0.0, 0.38, L.BAD, c)
    else:
        stem(W0, 0.62, L.BAD, c); stem(WMAX, 0.19, L.BAD, c); stem(-WMAX, 0.19, L.BAD, c)
    fig.add_annotation(x=W0, y=1.06, xref=ax("x", c), yref=ax("y", c), text="w&#8320;",
                       showarrow=False, yanchor="bottom",
                       font=dict(size=L.pt(5.5), color=L.GRAY))
    # the map goes below the baseline, where nothing else competes for space
    fig.add_annotation(x=0.25, y=-0.18, xref=ax("x", c), yref=ax("y", c), text=expr,
                       showarrow=False, xanchor="center", yanchor="top",
                       font=dict(size=L.pt(6.0), color="black"))

# ===================== row 2: what recovers from it ======================
# Severity axes: log for the Gaussian and log-normal widths; logit for the stuck fractions, which run up to 0.99 and
# would bunch against 1 on a log axis (stage 4d added f 0.9, 0.95, 0.99, where stuck-at-zero changes most).
XMAP = {"gaussian": np.log10, "lognormal": np.log10, "stuck_zero": lambda f: np.log(np.asarray(f) / (1 - np.asarray(f))),
        "stuck_sat": lambda f: np.log(np.asarray(f) / (1 - np.asarray(f)))}
for i, (key, letter, name, expr, xlab) in enumerate(FAULTS):
    c = i + 1
    d = L.dat(f"fig7_rec_{key}.dat")
    d = d[d.n >= MINREPS]
    fig.add_hline(y=1.0, line=dict(color=L.GRAY, width=L.pt(0.6), dash="dash"),
                  row=2, col=c, exclude_empty_subplots=False)
    xs = XMAP[key](d.sev.values)
    YLO = YLOS[key]
    for col, colour, _, dash, ceil in SERIES:
        r = lambda q: np.clip(d[q] / CEIL[col], YLO, None) if col == "imp" else d[q] / CEIL[col]   # only the floor is clipped
        fig.add_trace(go.Scatter(
            x=np.concatenate([xs, xs[::-1]]),
            y=np.concatenate([r(f"{col}hi"), r(f"{col}lo")[::-1]]), mode="lines",
            fill="toself", fillcolor=L.rgba(colour, 0.16), line=dict(width=0),
            hoverinfo="skip"), row=2, col=c)
        fig.add_trace(go.Scatter(
            x=xs, y=r(col), mode="lines+markers",
            line=dict(color=colour, width=L.pt(1.0), dash=dash),
            marker=dict(size=L.pt(2.0), color=colour), hoverinfo="skip"), row=2, col=c)

    for x, v in zip(xs, d["imp"] / CEIL["imp"]):
        if v < YLO:                                                   # the value where the floor leaves the panel, once
            fig.add_annotation(x=x, y=YLO, xref=ax("x", c + 4), yref=ax("y", c + 4),
                               text=f"{v:.2f}".lstrip("0"), showarrow=False, yanchor="bottom", xanchor="center",
                               yshift=L.pt(1.5), font=dict(size=L.pt(5.5), color=L.BAD))
            break

# one shared legend, in the gap between the rows
for k, (_, colour, lab, _, _) in enumerate(SERIES):
    fig.add_annotation(x=k * 0.180, y=D_REC[1] + 11.0 * PT, xref="paper", yref="paper",
                       text="&#8212; " + lab, showarrow=False,
                       xanchor="left", yanchor="bottom",
                       font=dict(size=L.pt(6.0), color=colour))
fig.add_annotation(x=0.0, y=D_REC[1] + 3.0 * PT, xref="paper", yref="paper",
                   text=f"divided by the backprop control (- - = 1): {REF:.3f}, the undamaged network through the same fine-tune by backprop",
                   showarrow=False, xanchor="left", yanchor="bottom", font=dict(size=L.pt(5.5), color=L.GRAY))

# --------------------------------------------------------------- axes
fig.update_layout(**L.layout(TOTAL, margin=dict(l=L.pt(ML), r=L.pt(MR),
                                                t=L.pt(MT), b=L.pt(MB))))
for i, (key, letter, name, expr, xlab) in enumerate(FAULTS):
    c = i + 1
    d = L.dat(f"fig7_rec_{key}.dat")
    d = d[d.n >= MINREPS]
    fig.update_xaxes(visible=False, range=[-1.25, 1.75], domain=COLS[i], row=1, col=c)
    fig.update_yaxes(visible=False, range=[-0.75, 1.35], domain=D_DIST, row=1, col=c)

    sev = [float(v) for v in d.sev]; tx = [float(t) for t in XMAP[key](sev)]
    # Every run severity gets a tick, but the axis cannot carry eight labels: keep the endpoints and anything at least
    # GAP of the axis span from the last kept label.
    GAP = 0.14 * (tx[-1] - tx[0])
    kept, last = [0], tx[0]
    for j in range(1, len(sev) - 1):
        if tx[j] - last >= GAP:
            kept.append(j); last = tx[j]
    while len(kept) > 1 and tx[-1] - tx[kept[-1]] < GAP:
        kept.pop()
    keep = {sev[j] for j in kept} | {sev[-1]}
    # sigma/RMS spans 0.24 to 35, so integer formatting would print the two
    # sub-unit ticks as "0" and "1". Format by magnitude, not by panel.
    fmt = lambda v: ("%g" % v) if v >= 1 else ("%.2f" % v).lstrip("0")
    lab = [fmt(v) if v in keep else "" for v in sev]
    pad = 0.06 * (tx[-1] - tx[0])
    fig.update_xaxes(L.AXIS, range=[tx[0] - pad, tx[-1] + pad],
                     tickvals=tx, ticktext=lab, tickangle=0,
                     title_text=xlab, title_standoff=L.pt(2),
                     tickfont=dict(size=L.pt(5.5)), domain=COLS[i], row=2, col=c)
    YLO = YLOS[key]
    step = 0.02 if YHI - YLO < 0.12 else (0.05 if YHI - YLO < 0.4 else 0.1)
    tv = [round(t, 2) for t in np.arange(np.ceil(YLO / step) * step, 1.0001, step) if YLO <= t <= YHI + 1e-9]
    fig.update_yaxes(L.AXIS, range=[YLO, YHI], tickvals=tv, tickfont=dict(size=L.pt(5.5)),
                     ticktext=[f"{t:.2f}" for t in tv],
                     title_text="accuracy / backprop control" if i == 0 else None,
                     title_standoff=L.pt(3), domain=D_REC, row=2, col=c)

    # (a)-(d) name the fault, so the text can cite a distortion type directly
    fig.add_annotation(x=np.mean(COLS[i]), y=1.0 + 3.0 * PT, xref="paper", yref="paper",
                       text=f"<b>({letter})</b> {name}", showarrow=False,
                       xanchor="center", yanchor="bottom", align="center",
                       font=dict(size=L.pt(7.0), color="black"))

L.save(fig, "fig7_recovery")
